const path="/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/14.csv";
const csv=await tools.Read({file_path:path});
if(typeof csv!=="string") throw new Error("Expected CSV text");
const rows=csv.trim().split("\n").slice(1).map(line=>{const [truckId,at,lat,lon,engineOn,odometer]=line.split(",");const rad=x=>x*Math.PI/180;const a=Math.sin(rad(Number(lat)-28.9672)/2)**2+Math.cos(rad(28.9672))*Math.cos(rad(Number(lat)))*Math.sin(rad(Number(lon)+98.4786)/2)**2;return {truckId,at,dist_m:6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)),line};});
const time=Date.parse("2026-07-20T16:21:13Z");
text({source:path,row_count:rows.length,truck24:rows.filter(r=>r.truckId==="24").map(r=>r.line),pings_in_requested_window:rows.filter(r=>Date.parse(r.at)>=time-600000&&Date.parse(r.at)<=time+600000).length,nearest_within_90_minutes:rows.filter(r=>Math.abs(Date.parse(r.at)-time)<=5400000).sort((a,b)=>a.dist_m-b.dist_m).slice(0,10),nearest_all_day:rows.sort((a,b)=>a.dist_m-b.dist_m).slice(0,5)});
